<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ApiError } from '@/api/client'; import { getOperationalReports, type ReportsPayload } from '@/api/operations'; import { getSession } from '@/api/session';
const router = useRouter(); const data = ref<ReportsPayload | null>(null); const error = ref<string | null>(null); const filters = reactive({ search: '', state: '', convocation: '' }); const label = (value: string) => ({ sin_iniciar: 'Sin iniciar', borrador: 'Borrador', en_revision: 'En revisión', correccion_solicitada: 'Corrección solicitada', aprobado: 'Aprobado' }[value] ?? value);
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'coordinador') { await router.replace('/panel'); return; } data.value = await getOperationalReports(filters); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar el informe.'; } };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Coordinación</p><h1>Seguimiento operativo</h1><p>Estado de los sílabos dentro de la carrera activa.</p></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><form class="filter-form" @submit.prevent="load"><label>Buscar<input v-model="filters.search" /></label><label>Convocatoria<select v-model="filters.convocation"><option value="">Todas</option><option v-for="item in data?.convocations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Estado<select v-model="filters.state"><option value="">Todos</option><option v-for="value in ['sin_iniciar','borrador','en_revision','correccion_solicitada','aprobado']" :key="value" :value="value">{{ label(value) }}</option></select></label><button>Aplicar</button></form><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><section class="detail-card"><h2>Indicadores</h2><p>Total: {{ data.indicators.total }} · Acción docente: {{ data.indicators.teacher_action }} · Acción de Coordinación: {{ data.indicators.coordination_action }} · Aprobados: {{ data.indicators.approved }} · Avance promedio: {{ data.indicators.average_completion }}%</p></section><div class="table-wrap"><table><thead><tr><th>Asignatura</th><th>Docentes</th><th>Estado</th><th>Avance</th><th>Observaciones</th><th></th></tr></thead><tbody><tr v-for="item in data.syllabi.data" :key="item.id"><td>{{ item.subject }}<small>{{ item.code }} · {{ item.period }}</small></td><td>{{ item.teachers.join(', ') }}</td><td>{{ label(item.state) }}</td><td>{{ item.completion }}%</td><td>{{ item.unresolved_observations }}</td><td><RouterLink v-if="item.latest_revision_id" class="back-link" :to="`/coordinacion/revisiones/${item.latest_revision_id}`">Ver revisión</RouterLink></td></tr></tbody></table></div></template></main></template>
